CREATE DATABASE IF NOT EXISTS logicraft CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
CREATE USER IF NOT EXISTS 'logicraft'@'%' IDENTIFIED BY 'logicraft_demo';
GRANT ALL PRIVILEGES ON logicraft.* TO 'logicraft'@'%';
USE logicraft;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, full_name VARCHAR(120) NOT NULL, role VARCHAR(30) NOT NULL, password_hash VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, INDEX ix_users_role(role));
CREATE TABLE IF NOT EXISTS records (id INT AUTO_INCREMENT PRIMARY KEY, module VARCHAR(50) NOT NULL, name VARCHAR(180) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'Active', reference VARCHAR(100) NOT NULL DEFAULT '', location VARCHAR(180) NOT NULL DEFAULT '', quantity DOUBLE NOT NULL DEFAULT 0, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX ix_records_module(module), INDEX ix_records_module_status(module,status), INDEX ix_records_name(name));
CREATE TABLE IF NOT EXISTS record_attributes (record_id INT NOT NULL, attribute VARCHAR(100) NOT NULL, attribute_value JSON NULL, PRIMARY KEY(record_id,attribute), INDEX ix_record_attributes_attribute(attribute), CONSTRAINT fk_attributes_record FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS status_events (id INT AUTO_INCREMENT PRIMARY KEY, record_id INT NOT NULL, status VARCHAR(40) NOT NULL, note TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_events_record(record_id), CONSTRAINT fk_events_record FOREIGN KEY(record_id) REFERENCES records(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fuel_logs (id INT AUTO_INCREMENT PRIMARY KEY, vehicle_id INT NOT NULL, liters DOUBLE NOT NULL, odometer_km DOUBLE NOT NULL, cost DOUBLE NOT NULL DEFAULT 0, filled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX ix_fuel_vehicle(vehicle_id), CONSTRAINT fk_fuel_vehicle FOREIGN KEY(vehicle_id) REFERENCES records(id));
